{
  "name": "cache-demo",
  "version": "1.0.0",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "lint": "turbo run lint",
    "test": "turbo run test",
    "benchmark": "bash benchmark.sh"
  },
  "devDependencies": {
    "turbo": "latest",
    "typescript": "^5.0.0"
  }
}

export function greet(name: string): string {
  return `Hello, ${name}! Welcome to the core package.`;
}

export function add(a: number, b: number): number {
  return a + b;
}

export function multiply(a: number, b: number): number {
  return a * b;
}

import { add, multiply } from '@cache-demo/core';

export function calculate(a: number, b: number): number {
  const sum = add(a, b);
  const product = multiply(a, b);
  return sum + product;
}

export function formatNumber(num: number): string {
  return num.toLocaleString();
}

export function isEven(num: number): boolean {
  return num % 2 === 0;
}

import { greet } from '@cache-demo/core';
import { calculate, formatNumber, isEven } from '@cache-demo/utils';

function main(): void {
  console.log(greet('Turborepo'));

  const result = calculate(10, 5);
  console.log(`Calculation result: ${formatNumber(result)}`);
  console.log(`Is ${result} even? ${isEven(result)}`);
}

export { main };

